+    private IntegrityReport inspect(Properties rules) {
+        List<Entry> entries = entriesOf(rules);
+        Map<String, List<Entry>> sameName = groupBy(entries, entry -> entry.name);
+        Map<String, List<Entry>> sameResolvedFile = groupBy(entries, Entry::resolvedIdentity);
+        Map<String, List<Entry>> sameDerivedName = groupBy(entries, Entry::derivedName);
+
+        for (Entry entry : entries) {
+            entry.shared = sameName.get(entry.name).size() > 1
+                    || (entry.resolvedIdentity() != null && sameResolvedFile.get(entry.resolvedIdentity()).size() > 1);
+            entry.broken = !entry.hasRegularFileDirectlyInFolder();
+            entry.empty = !entry.broken && fileHasNoViolations(entry.path);
+            entry.misplaced = !entry.name.equals(entry.derivedName);
+            entry.colliding = sameDerivedName.get(entry.derivedName).size() > 1;
+            entry.occupied = entry.misplaced && !entry.name.equals(entry.derivedName)
+                    && (pathNamesSomething(entry.derivedPath) || sameName.containsKey(entry.derivedName)
