+        Set<String> ownedFiles = new HashSet<>();
+        for (Entry entry : entries) {
+            if (entry.resolvedIdentity() != null && entry.isDirectRegularFile()) {
+                ownedFiles.add(entry.resolvedIdentity());
+            }
+        }
