+    private String deriveNameForIntegrity(String description) {
+        String name;
+        try {
+            name = fileNameStrategyHolder.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not derive a file name for rule '%s'", description), e);
+        }
+        return validateDerivedName(name, true);
+    }
