    public FreezingArchRule associateViolationLinesVia(ViolationLineMatcher matcher) {
        return new FreezingArchRule(delegate, store, matcher);
    }

    @Override
    public String toString() {
        return getClass().getSimpleName() + "{" + delegate + "}";
    }

