import static java.nio.charset.StandardCharsets.UTF_8;
import static java.util.stream.Collectors.toList;

/**
 * A text file based implementation of a {@link ViolationStore}.<br>
 * This {@link ViolationStore} will store the violations of every single {@link FreezingArchRule} in a dedicated file.<br>
 * It will keep an index of all stored rules as well as a mapping to the individual rule violation files in the same folder.
 * <p>
 * The store can be configured through the following properties:
 * <pre><code>
 * default.path=...               # string: the path of the folder where violation files will be stored
 * default.allowStoreCreation=... # boolean: whether to allow creating a new index file
 * default.allowStoreUpdate=...   # boolean: whether to allow updating any store file
 * default.fileNames=...          # random, description, or a RuleViolationFileNameStrategy class
 * default.integrity=...          # ignore, repair, or fail
 * </code></pre>
 */
@PublicAPI(usage = ACCESS)
public final class TextFileBasedViolationStore implements ViolationStore {
    private static final Logger log = LoggerFactory.getLogger(TextFileBasedViolationStore.class);

    private static final Pattern UNESCAPED_LINE_BREAK_PATTERN = Pattern.compile("(?<!\\\\)\\n");
    private static final Pattern DESCRIPTION_WORD_PATTERN = Pattern.compile("(?<![A-Za-z0-9])([A-Za-z0-9]{4,120})(?![A-Za-z0-9])");
    private static final Pattern ONLY_LINE_BREAKS_PATTERN = Pattern.compile("(?:\\r\\n|\\n|\\r)*");

    private static final String STORE_PATH_PROPERTY_NAME = "default.path";
    private static final String STORE_PATH_DEFAULT = "archunit_store";
    private static final String STORED_RULES_FILE_NAME = "stored.rules";
    private static final String ALLOW_STORE_CREATION_PROPERTY_NAME = "default.allowStoreCreation";
    private static final String ALLOW_STORE_CREATION_DEFAULT = "false";
    private static final String ALLOW_STORE_UPDATE_PROPERTY_NAME = "default.allowStoreUpdate";
    private static final String ALLOW_STORE_UPDATE_DEFAULT = "true";
    private static final String FILE_NAMES_PROPERTY_NAME = "default.fileNames";
    private static final String FILE_NAMES_RANDOM = "random";
    private static final String FILE_NAMES_DESCRIPTION = "description";
    private static final String INTEGRITY_PROPERTY_NAME = "default.integrity";
    private static final String INTEGRITY_IGNORE = "ignore";
    private static final String INTEGRITY_REPAIR = "repair";
    private static final String INTEGRITY_FAIL = "fail";

    private static final String[] INTEGRITY_VALUES = {INTEGRITY_REPAIR, INTEGRITY_FAIL, INTEGRITY_IGNORE};
    private static final ConcurrentHashMap<String, Object> STORE_LOCKS = new ConcurrentHashMap<>();

    private final RuleViolationFileNameStrategy ruleViolationFileNameStrategy;
    private final boolean strategyWasGivenToConstructor;

    private boolean storeCreationAllowed;
    private boolean storeUpdateAllowed;
    private Integrity integrity;
    private boolean fileNamesAreDerivable;
    private File storeFolder;
    private File storedRulesFile;
    private Properties storedRules;

    /**
     * Creates a standard {@link TextFileBasedViolationStore} that names rule violation files by random {@link UUID}s.
     *
     * @see #TextFileBasedViolationStore(RuleViolationFileNameStrategy)
     */
    public TextFileBasedViolationStore() {
        this.ruleViolationFileNameStrategy = __ -> UUID.randomUUID().toString();
        this.strategyWasGivenToConstructor = false;
    }

    /**
     * Creates a {@link TextFileBasedViolationStore} with a custom strategy for rule violation file naming.
     *
     * @param ruleViolationFileNameStrategy controls how the rule violation file name is derived from the rule description
     */
    public TextFileBasedViolationStore(RuleViolationFileNameStrategy ruleViolationFileNameStrategy) {
        if (ruleViolationFileNameStrategy == null) {
            throw new NullPointerException("ruleViolationFileNameStrategy must not be null");
        }
        this.ruleViolationFileNameStrategy = ruleViolationFileNameStrategy;
        this.strategyWasGivenToConstructor = true;
    }

    @Override
    public void initialize(Properties properties) {
        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
        integrity = Integrity.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_IGNORE));
        if (integrity == Integrity.REPAIR && !storeUpdateAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Integrity repair requires %s.%s=true",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        RuleViolationFileNameStrategy configuredStrategy = configureFileNameStrategy(properties);
        // The strategy is final for the lifetime of a store, but the no-argument constructor's
        // built-in strategy is selected by this property. A constructor strategy is deliberately
        // not replaceable by configuration.
        if (configuredStrategy != null) {
            // This is only possible for the no-argument constructor. The assignment is done via
            // the delegating holder below; keeping this branch makes the configuration check clear.
            fileNameStrategyHolder = configuredStrategy;
        } else {
            fileNameStrategyHolder = ruleViolationFileNameStrategy;
        }
        fileNamesAreDerivable = strategyWasGivenToConstructor
                || FILE_NAMES_DESCRIPTION.equals(properties.getProperty(FILE_NAMES_PROPERTY_NAME));

        try {
            storeFolder = new File(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT)).getCanonicalFile();
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
        storedRulesFile = new File(storeFolder, STORED_RULES_FILE_NAME);

        Object lock = lockFor(storeFolder);
        synchronized (lock) {
            initializeUnderLock();
        }
    }

    /*
     * The strategy selected by initialize is kept separately so a store can be initialized
     * repeatedly with different properties, as the surrounding freeze API does.
     */
    private RuleViolationFileNameStrategy fileNameStrategyHolder;

    private RuleViolationFileNameStrategy configureFileNameStrategy(Properties properties) {
        String configuredName = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
        if (strategyWasGivenToConstructor) {
            if (configuredName != null) {
                throw new StoreInitializationFailedException(String.format(
                        "Cannot configure %s when a RuleViolationFileNameStrategy was supplied to the constructor",
                        FILE_NAMES_PROPERTY_NAME));
            }
            return null;
        }

        if (configuredName == null || FILE_NAMES_RANDOM.equals(configuredName)) {
            return ruleDescription -> UUID.randomUUID().toString();
        }
        if (FILE_NAMES_DESCRIPTION.equals(configuredName)) {
            return TextFileBasedViolationStore::createDescriptionFileName;
        }

        try {
            Class<?> strategyClass = Class.forName(configuredName);
            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
                throw new IllegalArgumentException("does not implement RuleViolationFileNameStrategy");
            }
            Constructor<?> constructor = strategyClass.getConstructor();
            return (RuleViolationFileNameStrategy) constructor.newInstance();
        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException
                 | InvocationTargetException | IllegalArgumentException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot instantiate %s configured by %s=%s; it must be a RuleViolationFileNameStrategy with a public no-argument constructor",
                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configuredName), e);
        }
    }

    private void initializeUnderLock() {
        boolean indexExists = Files.exists(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS);
        if (!indexExists && !storeCreationAllowed) {
            throw new StoreInitializationFailedException(String.format(
                    "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
        }
        ensureStoreFolder();
        if (indexExists && (!Files.isRegularFile(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS)
                || !isPathDirectlyInFolder(storedRulesFile.toPath()))) {
            throw new StoreInitializationFailedException(String.format(
                    "The store index %s must be a regular file directly in the store folder",
                    storedRulesFile.getAbsolutePath()));
        }

        Properties loaded = indexExists ? loadRulesFrom(storedRulesFile) : new Properties();
        if (integrity == Integrity.IGNORE) {
            if (!indexExists) {
                writeIndexDuringInitialization(loaded);
            }
            storedRules = loaded;
            return;
        }

        IntegrityReport report = inspect(loaded);
        if (integrity == Integrity.FAIL) {
            if (!report.isEmpty()) {
                throw new StoreInitializationFailedException(report.message(storedRulesFile));
            }
            if (!indexExists) {
                writeIndexDuringInitialization(loaded);
            }
            storedRules = loaded;
            return;
        }

        repair(loaded, report);
        if (!indexExists || report.changed) {
            writeIndexDuringInitialization(loaded);
        }
        storedRules = loaded;
    }

    private void ensureStoreFolder() {
        try {
            if (!storeFolder.exists()) {
                if (!storeFolder.mkdirs() && !storeFolder.isDirectory()) {
                    throw new IOException("Could not create store folder");
                }
            }
            }
            if (!storeFolder.isDirectory()) {
                throw new IOException("Store path is not a directory");
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot create or access store folder %s", storeFolder.getAbsolutePath()), e);
        }
    }

    private Properties loadRulesFrom(File file) {
        Properties result = new Properties();
        try (FileInputStream inputStream = new FileInputStream(file)) {
            result.load(inputStream);
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
        return result;
    }

    private IntegrityReport inspect(Properties rules) {
        List<Entry> entries = entriesOf(rules);
        Map<String, List<Entry>> sameName = groupBy(entries, entry -> entry.name);
        Map<String, List<Entry>> sameResolvedFile = groupBy(entries, Entry::resolvedIdentity);
        Map<String, List<Entry>> sameDerivedName = groupBy(entries, entry -> entry.derivedName);

        for (Entry entry : entries) {
            entry.shared = sameName.get(entry.name).size() > 1
                    || (entry.resolvedIdentity() != null && sameResolvedFile.get(entry.resolvedIdentity()).size() > 1);
            entry.broken = !entry.hasRegularFileDirectlyInFolder();
            entry.empty = !entry.broken && fileHasNoViolations(entry.path);
            entry.misplaced = !entry.name.equals(entry.derivedName);
            entry.colliding = sameDerivedName.get(entry.derivedName).size() > 1;
            entry.occupied = entry.misplaced && !entry.name.equals(entry.derivedName)
                    && (pathNamesSomething(entry.derivedPath) || sameName.containsKey(entry.derivedName)
                    || !isPathDirectlyInFolder(entry.derivedPath));
        }

        Set<String> ownedFiles = new HashSet<>();
        for (Entry entry : entries) {
            if (entry.resolvedIdentity() != null && entry.isDirectRegularFile()) {
                ownedFiles.add(entry.resolvedIdentity());
            }
        }
        List<String> unownedFiles = directUnownedFiles(ownedFiles);
        return new IntegrityReport(entries, unownedFiles);
    }

    private List<Entry> entriesOf(Properties rules) {
        List<Entry> result = new ArrayList<>();
        for (String description : rules.stringPropertyNames()) {
            String name = rules.getProperty(description);
            String derivedName = fileNamesAreDerivable ? deriveNameForIntegrity(description) : name;
            result.add(new Entry(description, name, derivedName));
        }
        return result;
    }

    private String deriveNameForIntegrity(String description) {
        String name;
        try {
            name = fileNameStrategyHolder.createRuleFileName(description);
        } catch (RuntimeException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not derive a file name for rule '%s'", description), e);
        }
        return validateDerivedName(name, true);
    }

    private String deriveNameForSave(String description) {
        String name;
        try {
            name = fileNameStrategyHolder.createRuleFileName(description);
        } catch (RuntimeException e) {
            throw new StoreUpdateFailedException(String.format(
                    "Could not derive a file name for rule '%s'", description));
        }
        return validateDerivedName(name, false);
    }

    private String validateDerivedName(String name, boolean duringInitialization) {
        if (name == null || name.trim().isEmpty()) {
            String message = "RuleViolationFileNameStrategy returned no file name";
            if (duringInitialization) {
                throw new StoreInitializationFailedException(message);
            }
            throw new StoreUpdateFailedException(message);
        }
        return name;
    }

    private void repair(Properties rules, IntegrityReport report) {
        for (Entry entry : report.entries) {
            if (entry.shared) {
                continue;
            }
            if (entry.broken) {
                rules.remove(entry.description);
                report.changed = true;
            } else if (entry.empty) {
                deleteNamedFile(entry.path);
                rules.remove(entry.description);
                report.changed = true;
            }
        }

        for (Entry entry : report.entries) {
            if (entry.shared || entry.broken || entry.empty || entry.colliding || entry.occupied || !entry.misplaced) {
                continue;
            }
            moveNamedFile(entry.path, entry.derivedPath);
            rules.remove(entry.description);
            rules.setProperty(ensureUnixLineBreaks(entry.description), ensureUnixLineBreaks(entry.derivedName));
            report.changed = true;
        }
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (lockFor(storeFolder)) {
            Properties current = currentRules();
            storedRules = current;
            return current.containsKey(ensureUnixLineBreaks(rule.getDescription()));
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        synchronized (lockFor(storeFolder)) {
            Properties current = currentRules();
            String description = ensureUnixLineBreaks(rule.getDescription());
            String existingName = current.getProperty(description);

            if (violations.isEmpty() && integrity == Integrity.REPAIR && existingName != null) {
                forgetRuleUnderRepair(current, description, existingName);
            } else if (!violations.isEmpty()) {
                String fileName = existingName != null ? existingName : deriveNameForSave(description);
                saveViolations(current, description, fileName, violations, existingName != null);
            }
            storedRules = current;
        }
    }

    private Properties currentRules() {
        if (storedRulesFile == null
                || !Files.isRegularFile(storedRulesFile.toPath(), LinkOption.NOFOLLOW_LINKS)
                || !isPathDirectlyInFolder(storedRulesFile.toPath())) {
            throw new StoreUpdateFailedException("The store index is not a regular file directly in the store folder");
        }
        return loadRulesForUpdate(storedRulesFile);
    }

    private Properties loadRulesForUpdate(File file) {
        Properties result = new Properties();
        try (FileInputStream inputStream = new FileInputStream(file)) {
            result.load(inputStream);
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
        return result;
    }

    private void saveViolations(Properties rules, String description, String fileName, List<String> violations, boolean existingEntry) {
        Path target = pathFor(fileName);
        ensureWritableTarget(target, existingEntry, fileName);
        boolean targetExisted = pathNamesSomething(target);
        byte[] previousContents = null;
        if (targetExisted) {
            try {
                previousContents = Files.readAllBytes(target);
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }

        String oldValue = rules.getProperty(description);
        if (!existingEntry) {
            if (pathNamesSomething(target) || recordsName(rules, fileName)) {
                throw new StoreUpdateFailedException(String.format(
                        "Cannot store rule '%s': file '%s' is already occupied", description, fileName));
            }
            rules.setProperty(description, ensureUnixLineBreaks(fileName));
        }

        Path temporary = null;
        try {
            temporary = Files.createTempFile(storeFolder.toPath(), ".archunit-violation-", ".tmp");
            Files.write(temporary, violationsText(violations).getBytes(UTF_8));
            moveReplacing(temporary, target);
            writeIndex(rules);
        } catch (IOException e) {
            restoreTarget(target, targetExisted, previousContents);
            if (!existingEntry) {
                rules.remove(description);
            } else if (oldValue != null) {
                rules.setProperty(description, oldValue);
            }
            deleteIfExists(temporary);
            throw new StoreUpdateFailedException(e);
        } catch (RuntimeException e) {
            restoreTarget(target, targetExisted, previousContents);
            if (!existingEntry) {
                rules.remove(description);
            } else if (oldValue != null) {
                rules.setProperty(description, oldValue);
            }
            deleteIfExists(temporary);
            throw e;
        }
    }

    private void restoreTarget(Path target, boolean targetExisted, byte[] previousContents) {
        try {
            if (targetExisted) {
                Files.write(target, previousContents);
            } else {
                Files.deleteIfExists(target);
            }
        } catch (IOException ignored) {
            // The attempted rollback cannot obscure the original update failure.
        }
    }

    private void forgetRuleUnderRepair(Properties rules, String description, String fileName) {
        Path path = pathFor(fileName);
        boolean shared = recordsFileWithAnotherEntry(rules, description, fileName, path);
        if (!shared && isRegularFileDirectlyInFolder(path)) {
            try {
                deleteNamedFile(path);
            } catch (RuntimeException e) {
                throw new StoreUpdateFailedException(e);
            }
        }

        rules.remove(description);
        try {
            writeIndex(rules);
        } catch (RuntimeException e) {
            rules.setProperty(description, fileName);
            throw e;
        }
    }

    private boolean recordsFileWithAnotherEntry(Properties rules, String description, String fileName, Path path) {
        String identity = resolvedIdentity(path);
        for (String otherDescription : rules.stringPropertyNames()) {
            if (otherDescription.equals(description)) {
                continue;
            }
            String otherName = rules.getProperty(otherDescription);
            if (fileName.equals(otherName)) {
                return true;
            }
            if (identity != null && identity.equals(resolvedIdentity(pathFor(otherName)))) {
                return true;
            }
        }
        return false;
    }

    private String violationsText(List<String> violations) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(violation)).append("\n");
        }
        return builder.toString();
    }

    private void ensureWritableTarget(Path target, boolean existingEntry, String fileName) {
        if (!isPathDirectlyInFolder(target) || isIndexPath(target) || STORED_RULES_FILE_NAME.equals(fileName)) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot store violations in unsafe file '%s'", fileName));
        }
        if (Files.exists(target, LinkOption.NOFOLLOW_LINKS) && !Files.isRegularFile(target, LinkOption.NOFOLLOW_LINKS)) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot store violations in non-regular file '%s'", fileName));
        }
        if (Files.isSymbolicLink(target)) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot store violations through symbolic link '%s'", fileName));
        }
        if (!existingEntry && pathNamesSomething(target)) {
            throw new StoreUpdateFailedException(String.format(
                    "Cannot overwrite unowned file '%s'", fileName));
        }
    }

    private boolean recordsName(Properties rules, String name) {
        for (String description : rules.stringPropertyNames()) {
            if (name.equals(rules.getProperty(description))) {
                return true;
            }
        }
        return false;
